describe("local practice", () => {
  it("meet the cypress runner", () => {
    cy.visit("/practice.html");
    cy.document().then(doc => { doc.body.innerHTML = "<h1>Library</h1>"; });
    cy.contains("h1", "Library").should("be.visible");
  });
});

describe("local practice", () => {
  it("select a clear target", () => {
    cy.visit("/practice.html");
    cy.document().then(doc => { doc.body.innerHTML = '<button data-cy="borrow">Borrow</button>'; });
    cy.get('[data-cy="borrow"]').should("have.text", "Borrow");
  });
});

describe("local practice", () => {
  it("type into a field", () => {
    cy.visit("/practice.html");
    cy.document().then(doc => { doc.body.innerHTML = '<label for="title">Title</label><input id="title">'; });
    cy.get("#title").type("Moon").should("have.value", "Moon");
  });
});

describe("local practice", () => {
  it("click and check the effect", () => {
    cy.visit("/practice.html");
    cy.document().then(doc => { const b=doc.createElement("button"); b.textContent="Save"; b.onclick=()=>b.textContent="Done"; doc.body.replaceChildren(b); });
    cy.contains("button", "Save").click();
    cy.contains("button", "Done").should("be.visible");
  });
});

describe("local practice", () => {
  it("retry an assertion", () => {
    cy.visit("/practice.html");
    cy.document().then(doc => { doc.body.innerHTML="<p>Ready</p>"; });
    cy.contains("p", "Ready").should("be.visible");
  });
});

describe("local practice", () => {
  it("read a yielded value", () => {
    cy.visit("/practice.html");
    cy.document().then(doc => { doc.body.innerHTML="<p>Moon</p>"; });
    cy.get("p").then($p => { expect($p.text()).to.equal("Moon"); });
  });
});

describe("local practice", () => {
  it("work with checkboxes", () => {
    cy.visit("/practice.html");
    cy.document().then(doc => { doc.body.innerHTML='<label><input id="remember" type="checkbox">Remember</label>'; });
    cy.get("#remember").check().should("be.checked");
  });
});

describe("local practice", () => {
  it("select a dropdown value", () => {
    cy.visit("/practice.html");
    cy.document().then(doc => { doc.body.innerHTML='<select id="size"><option value="s">Small</option><option value="l">Large</option></select>'; });
    cy.get("#size").select("l").should("have.value", "l");
  });
});

describe("local practice", () => {
  it("count a collection", () => {
    cy.visit("/practice.html");
    cy.document().then(doc => { doc.body.innerHTML="<ul><li>Moon</li><li>Ocean</li></ul>"; });
    cy.get("li").should("have.length", 2);
  });
});

describe("local practice", () => {
  it("intercept a request", () => {
    cy.intercept("GET", "/books.json", { body: [{ title: "Moon" }] }).as("books");
    cy.visit("/practice.html");
    cy.window().then(win => win.fetch("/books.json"));
    cy.wait("@books").its("response.statusCode").should("eq", 200);
  });
});

describe("local practice", () => {
  it("keep tests independent", () => {
    cy.visit("/practice.html");
    cy.window().then(win => { win.localStorage.setItem("theme", "light"); });
    cy.window().its("localStorage").invoke("getItem", "theme").should("eq", "light");
  });
});

describe("local practice", () => {
  it("review failures and screenshots", () => {
    cy.visit("/practice.html");
    cy.document().then(doc => { doc.body.innerHTML="<h1>Library</h1>"; });
    cy.contains("h1", "Library").should("be.visible");
    cy.screenshot("library-page");
  });
});
